'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { ProductCard } from '@/modules/shop/components/ProductCard';
import { shopService } from '@/modules/shop/services/shopService';
import { ShopItem, Category } from '@/modules/shop/types';
import { Loader2, Plus } from 'lucide-react';

export default function CategoryListingPage() {
    const params = useParams();
    const categoryId = params.category as string;

    const [items, setItems] = useState<ShopItem[]>([]);
    const [category, setCategory] = useState<Category | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const load = async () => {
            setLoading(true);
            const [catInfo, catItems] = await Promise.all([
                shopService.getCategoryById(categoryId),
                shopService.getItems(categoryId)
            ]);
            setCategory(catInfo || null);
            setItems(catItems);
            setLoading(false);
        };
        load();
    }, [categoryId]);

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[400px] gap-4">
                <Loader2 className="animate-spin text-emerald-600 w-10 h-10" />
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Loading Catalog...</p>
            </div>
        );
    }

    if (!category) {
        return (
            <div className="text-center py-20">
                <h1 className="text-4xl font-black text-slate-900 mb-4">Category Not Found</h1>
                <p className="text-slate-500 font-medium">Please select a valid category from the menu.</p>
            </div>
        );
    }

    return (
        <div className="space-y-12 animate-in fade-in duration-700">
            {/* Page Header */}
            <div className="max-w-3xl">
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 capitalize mb-4">
                    <span>Home</span>
                    <span>/</span>
                    <span className="text-slate-900">{category.name}</span>
                </div>
                <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-4 leading-tight">
                    {category.title}
                </h1>
                <p className="text-lg text-slate-500 font-medium leading-relaxed">
                    {category.subtitle}
                </p>
            </div>

            {/* Product Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {items.map((item) => (
                    <ProductCard key={item.id} item={item} />
                ))}
            </div>

            {/* Load More (UI Only) */}
            <div className="flex flex-col items-center pt-12">
                <button className="flex items-center gap-3 px-8 py-4 border-2 border-emerald-600 text-emerald-600 rounded-full text-sm font-black uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all shadow-xl shadow-emerald-100/50">
                    Load More Products
                    <Plus size={18} />
                </button>
            </div>
        </div>
    );
}
